"""Author-maintained v0.2 curriculum. Never import third-party lesson text."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
legacy=json.loads((root/'tests/legacy-course.json').read_text())
META='https://metanit.com/rust/tutorial/'
BOOK='https://doc.rust-lang.org/book/'
BROWN='https://rust-book.cs.brown.edu/'
STANFORD='https://web.stanford.edu/class/cs110l/'
def readings(*items): return [dict(title=t,url=u) for t,u in items]
tracks=[dict(id='intro',title='С нуля',description='Никогда не программировали? Начните здесь.',level='Начинающий'),dict(id='core',title='Основы Rust',description='Владение данными, коллекции и проектирование.',level='Базовый'),dict(id='advanced',title='Продвинутый Rust',description='Обобщения, lifetimes, ошибки и конкурентность.',level='Продвинутый')]
modules=[]
def module(id,track,title,description,outcome):
 modules.append(dict(id=id,track=track,title=title,description=description,number=len(modules)+1,outcome=outcome))
module('orientation','intro','Ваши первые строки','Как читать программу, создавать и изменять переменные.','Понимать роль компилятора, main, let и mut.')
module('values','intro','Значения и типы','Типы, shadowing, логика и константы.','Предсказывать значения и выбирать подходящие типы.')
module('functions','intro','Функции без загадок','Объявление, параметры, результат и композиция.','Разбивать вычисление на понятные функции.')
intro=[]; advanced=[]
def add(id,mod,title,summary,heading,text,example,task,starter,solution,checks,hints,mistake,outcome,extra,extra_text,refs=None,minutes=8):
 track=next(m['track'] for m in modules if m['id']==mod)
 tests='#[cfg(test)]\nmod rustpath_tests {\n use super::*;\n'+'\n'.join(f' #[test]\n fn case_{i}() {{ {check} }}' for i,(_,check) in enumerate(checks,1))+'\n}'
 target=intro if track=='intro' else advanced
 target.append(dict(id=id,module=mod,track=track,kind='code',title=title,minutes=minutes,xp=30 if track=='intro' else 75,summary=summary,outcome=outcome,common_mistake=mistake,theory=[dict(heading=heading,text=text,example=example),dict(heading=extra,text=extra_text,example=None)],task=task,starter=starter,solution=solution,tests=tests,hints=hints,test_labels=[l for l,_ in checks],readings=refs or readings(('Metanit: руководство Rust',META),('The Rust Book',BOOK)),visual=None,quiz=None))
def quiz(id,mod,title,summary,heading,text,example,question,options,correct,explanation,hint,outcome):
 intro.append(dict(id=id,module=mod,track='intro',kind='quiz',title=title,minutes=5,xp=20,summary=summary,outcome=outcome,common_mistake='Не пытайтесь запомнить ответ: объясните, почему остальные варианты не подходят.',theory=[dict(heading=heading,text=text,example=example)],task='Выберите один ответ. После попытки появится объяснение.',starter='',solution='',tests='',hints=[hint],test_labels=[],readings=readings(('Metanit: основы языка',META),('The Rust Book',BOOK)),visual=None,quiz=dict(question=question,options=options,correct=correct,explanation=explanation)))
quiz('intro-rust','orientation','Знакомство с Rust','Что делает компилятор и почему ошибки помогают.','От текста к работающей программе','Rust — компилируемый язык. Мы записываем инструкции в исходном коде; rustc проверяет их и создаёт исполняемую программу. Проверка типов и правил владения происходит до запуска. Но компилятор не доказывает правильность бизнес-логики: для этого нужны тесты. На сайте установка Rust не требуется — код проверяет отдельный сервис.',None,'Какая ошибка обычно обнаруживается до запуска программы?',['Функция возвращает строку, хотя обещает число','Программа считает неверную скидку, но типы совпадают','Сервису не хватает места на диске во время работы'],0,'Несовпадение объявленного типа результата — ошибка компиляции. Неверная скидка может успешно скомпилироваться, а отсутствие места относится к условиям выполнения.','Разделите проверку структуры программы и проверку её смысла.','Различать компиляцию, выполнение и проверку поведения.')
quiz('intro-main','orientation','Как читается программа','Точка входа, строки и вызов функции.','Начинаем с main','fn main() — точка входа обычной исполняемой Rust-программы. Фигурные скобки ограничивают тело функции. Вызов вида print_message() передаёт управление другой функции, затем выполнение main продолжается. println! — макрос для вывода строки, поэтому после имени стоит !. В учебных задачах вместо main часто дана функция: тесты вызывают её сами.','fn main() {\n    println!("Сначала");\n    announce();\n}\nfn announce() {\n    println!("Затем");\n}','В каком порядке появятся строки?',['Затем, потом Сначала','Сначала, потом Затем','Порядок зависит от места определения announce'],1,'Выполнение начинается в main. Сначала выполняется первый println!, затем вызывается announce. Положение определения функции в файле не задаёт порядок вызовов.','Проследите именно вызовы, а не порядок определений.','Читать тело функции последовательно и находить вызовы.')
add('intro-let','orientation','Переменная: имя для значения','Создаём первую переменную через let.','Объявление и использование','let связывает имя со значением. В let coins = 7; имя coins позволяет повторно использовать число 7. Знак = здесь задаёт начальное значение, а не проверяет равенство. Инструкция заканчивается ;. Мы уже подготовили функцию: пока изменяйте только её тело. Последняя строка без ; отдаёт результат тесту.','let coins = 7;\nlet bonus = 2;\nlet total = coins + bonus;','Внутри coins создайте переменную amount со значением 12 и верните её. Внешнюю строку pub fn менять не нужно.','pub fn coins() -> i32 {\n    let amount = 0;\n    amount\n}','pub fn coins() -> i32 { let amount = 12; amount }',[('Начальное значение','assert_eq!(coins(),12);')],['Замените начальное значение amount.','Переменная объявляется так: let amount = 12;'], 'Запись amount == 12 сравнивает значения, а не объявляет переменную.','Объявлять и читать переменную.','Почему в задаче уже есть функция','Тесту нужна точка, из которой он получает ответ. Сейчас функция — только готовая оболочка; как написать свою, разберём в третьем модуле.')
add('intro-mut','orientation','Когда значение меняется','mut разрешает повторное присваивание.','Неизменяемость по умолчанию','После let score = 10; нельзя присвоить score новое значение. Напишите let mut score = 10;, если изменение необходимо. += прибавляет число к текущему значению. mut не меняет тип: в числовую переменную всё ещё нельзя записать строку.','let mut score = 10;\nscore += 5;','Исправьте код: разрешите изменение points и добавьте к ним 3. Итог должен быть 10.','pub fn points() -> i32 {\n    let points = 7;\n    points += 3;\n    points\n}','pub fn points() -> i32 { let mut points=7; points+=3; points }',[('Обновление переменной','assert_eq!(points(),10);')],['Компилятор укажет на присваивание неизменяемой переменной.','Добавьте mut после let.'],'Новая строка let points = ... создаёт новое связывание. Это shadowing, а не изменение старого.','Использовать изменяемое связывание осознанно.','Что говорит ошибка E0384','Если rustc пишет cannot assign twice to immutable variable, найдите объявление переменной. Решение не всегда mut: иногда правильнее пересчитать значение новым let.')
add('intro-types','values','Тип — договор о данных','Числа, bool и явная аннотация.','Аннотация после двоеточия','В let count: u32 = 4; двоеточие вводит тип. u32 хранит целые числа от 0 до 2³²−1, i32 допускает отрицательные значения, bool — true или false. Rust часто выводит тип из контекста, но параметры функции должны иметь явные типы. Ноль допустим для u32.','let ready: bool = true;\nlet temperature: i32 = -5;\nlet count: u32 = 0;','Создайте переменную minutes типа u32 со значением 60. Верните minutes.','pub fn minutes() -> u32 {\n    let minutes: u32 = 0;\n    minutes\n}','pub fn minutes() -> u32 { let minutes: u32=60; minutes }',[('Значение u32','assert_eq!(minutes(),60u32);')],['Сигнатура функции уже задаёт тип результата u32.','Нужно let minutes: u32 = 60;'],'Знаковый i32 и беззнаковый u32 не взаимозаменяемы автоматически.','Читать простые аннотации типов.','Вывод типа — не отсутствие типа','Запись let count = 4; тоже типизирована: компилятор выводит тип. В языке нет неявной переменной «любого типа».')
add('intro-shadow','values','Новое значение, то же имя','Shadowing и область видимости.','Новое let — новое связывание','let value = value + 1; создаёт новое связывание, которое скрывает прежнее. Оно может даже иметь другой тип. Вложенный блок задаёт собственную область: переменные, созданные внутри, недоступны после его завершения. Значение блока — последнее выражение без ;.','let text = "Rust";\nlet text = text.len(); // теперь usize','Сначала объявите count = 4. Затем новым let count = count * 3; получите 12 и верните count.','pub fn shadowed() -> i32 {\n    let count = 4;\n    // Создайте новое связывание\n    count\n}','pub fn shadowed() -> i32 { let count=4; let count=count*3; count }',[('Результат преобразования','assert_eq!(shadowed(),12);')],['Старое значение можно использовать справа от =.','Добавьте let count = count * 3;'],'Shadowing не требует mut: старое значение не изменяется.','Различать изменение и новое связывание.','Проверка поведения, а не стиля','Unit-тест проверит число 12, но не докажет использование let. Поэтому соблюдение учебного приёма нужно проверять чтением своего кода, а не только зелёным результатом.')
add('intro-bool','values','Условия из двух частей','Сравнения и логическое И.','bool и операторы','Сравнение >= возвращает bool. && означает «оба условия истинны», || — «хотя бы одно». Операторы короткозамкнутые: второе условие && не вычисляется, если первое false. Для равенства используется ==, а не =.','let allowed = age >= 18 && has_ticket;','Верните true только если age >= 16 и есть билет has_ticket.','pub fn can_enter(age: u8, has_ticket: bool) -> bool {\n    false\n}','pub fn can_enter(age:u8,has_ticket:bool)->bool{age>=16 && has_ticket}',[('Возраст и билет','assert!(can_enter(16,true));'),('Нет билета','assert!(!can_enter(20,false));'),('Возраст недостаточен','assert!(!can_enter(15,true));')],['Оба требования обязательны, поэтому нужен &&.','Сравните age с 16 и соедините результат с has_ticket.'],'Оператор || ошибочно разрешил бы вход при выполнении только одного требования.','Составлять условия из нескольких bool-выражений.','Тестируйте границу','Минимальный допустимый возраст важен: >= 16 и > 16 дают разные результаты для 16.')
add('intro-const','values','Константы и единицы','Явный тип и читаемые имена.','const','const задаёт постоянное значение и требует явный тип. Имена констант принято писать SCREAMING_SNAKE_CASE. Значение должно быть допустимым константным выражением, а не результатом произвольного действия во время выполнения. Использование константы делает единицы вычисления очевидными.','const SECONDS_PER_MINUTE: u32 = 60;','Объявите SECONDS_PER_MINUTE = 60 и используйте её в to_seconds. minutes находится в диапазоне 0..=1000.','const SECONDS_PER_MINUTE: u32 = 0;\npub fn to_seconds(minutes: u32) -> u32 {\n    minutes * SECONDS_PER_MINUTE\n}','const SECONDS_PER_MINUTE:u32=60; pub fn to_seconds(minutes:u32)->u32{minutes*SECONDS_PER_MINUTE}',[('Одна минута','assert_eq!(to_seconds(1),60);'),('Ноль','assert_eq!(to_seconds(0),0);'),('Несколько минут','assert_eq!(to_seconds(12),720);')],['Измените значение константы, а не сигнатуру.','Проверьте, что у const указан тип u32.'],'Обычный let без mut не превращается в const: у них разные правила объявления и вычисления.','Использовать константу для коэффициента.','Не прячьте единицы','Имя SECONDS_PER_MINUTE поясняет коэффициент лучше, чем число 60 посреди сложной формулы.')
add('intro-function','functions','Объявляем функцию','Имя, тело и тип результата.','fn + имя + скобки','fn начинает объявление. После имени следуют скобки параметров, затем необязательный -> Type и тело в {}. Функция с -> i32 должна вернуть число. В этом тренажёре pub позволяет тесту вызвать функцию; полноценные модули и видимость рассмотрим позже.','pub fn base_score() -> i32 {\n    10\n}','Напишите функцию base_score без параметров. Она должна возвращать i32 со значением 25.','// Объявите здесь pub fn base_score() -> i32\n','pub fn base_score()->i32{25}',[('Вызов функции','assert_eq!(base_score(),25);')],['Ориентируйтесь на пример, но измените результат.','Сигнатура: pub fn base_score() -> i32.'],'Не добавляйте main: тесты вызывают именно base_score.','Самостоятельно объявлять простую функцию.','Объявление не запускает функцию','Код в теле выполняется только при вызове. Само определение функции не печатает и не вычисляет результат.')
add('intro-arguments','functions','Передаём аргументы','Параметры дают функции входные данные.','Параметр и аргумент','В fn triple(value: i32) параметр — имя value в объявлении. При triple(4) аргумент — переданное значение 4. Типы параметров обязательны. Несколько параметров разделяются запятыми, значения передаются по позиции.','pub fn triple(value: i32) -> i32 {\n    value * 3\n}\n// triple(4) вернёт 12','Напишите add_bonus(points, bonus), возвращающую сумму двух i32. Значения от -1000 до 1000.','pub fn add_bonus(points: i32, bonus: i32) -> i32 {\n    0\n}','pub fn add_bonus(points:i32,bonus:i32)->i32{points+bonus}',[('Два аргумента','assert_eq!(add_bonus(10,5),15);'),('Отрицательное значение','assert_eq!(add_bonus(-3,2),-1);'),('Ноль','assert_eq!(add_bonus(0,0),0);')],['Используйте оба параметра, а не фиксированный результат.','Последним выражением может быть points + bonus.'],'Не меняйте порядок и типы аргументов: это контракт с вызывающим кодом.','Различать параметр и аргумент.','Функция подходит многим входам','Три теста проверяют разные значения, чтобы решение не работало только для одного примера.',refs=readings(('Metanit: параметры функции',META+'2.11.php'),('The Rust Book: functions',BOOK+'ch03-03-how-functions-work.html')))
quiz('intro-return','functions','Почему важна точка с запятой','Выражение возвращает значение, инструкция — нет.','Последнее выражение','Тело функции может вернуть последнее выражение без ;. Если после него поставить ;, значение отбрасывается и блок возвращает (). Альтернатива — явный return value;, который завершает функцию. println! выводит текст, но не заменяет возвращаемое значение.','fn answer() -> i32 {\n    40 + 2\n}','Какое тело подходит для функции с результатом i32?',['{ 40 + 2; }','{ println!("42"); }','{ 40 + 2 }'],2,'Последнее выражение 40 + 2 без ; даёт i32. Остальные варианты возвращают (), поэтому не подходят к -> i32. Явный { return 42; } тоже был бы корректен.','Сравните тип выражения и тип результата всего блока.','Различать выражение, инструкцию и возвращаемое значение.')
add('intro-compose','functions','Соединяем функции','Маленькая задача из двух понятных частей.','Вызов внутри вычисления','Можно передать результат одной функции в другую или использовать его в арифметике. Разбиение полезно, когда каждый шаг имеет отдельный смысл. Сначала Rust вычисляет аргумент, затем выполняет вызов. Скобки помогают явно показать порядок.','fn double(x: i32) -> i32 { x * 2 }\nlet result = double(3) + 1;','Готовая double удваивает число. Используйте её в reward: результат должен быть double(base) + bonus. Все входы от -1000 до 1000.','fn double(x: i32) -> i32 { x * 2 }\npub fn reward(base: i32, bonus: i32) -> i32 {\n    0\n}','fn double(x:i32)->i32{x*2} pub fn reward(base:i32,bonus:i32)->i32{double(base)+bonus}',[('Вызов и сложение','assert_eq!(reward(4,3),11);'),('Не удваивать бонус','assert_eq!(reward(2,7),11);'),('Нулевой ввод','assert_eq!(reward(0,0),0);')],['Сначала передайте base в double.','Бонус прибавляется после удвоения: double(base) + bonus.'],'double(base + bonus) удвоит и бонус, изменив условие задачи.','Вызывать вспомогательные функции.','Что освоено','Вы уже можете объявлять переменные, менять значение, читать типы и создавать функции. Дальше выбирайте «Основы Rust»: там познакомимся с владением и коллекциями.')
