module('concurrency','advanced','Несколько потоков','JoinHandle, Arc, Mutex, каналы и Atomic.','Объяснять передачу данных и синхронизацию потоков.')
refs=readings(('Stanford CS110L: темы курса',STANFORD),('The Rust Book: generic types',BOOK+'ch10-00-generics.html'),('Metanit: ООП и generics',META))
add('adv-min','generic-api','Одна функция для разных типов','Generics и ограничения Ord + Copy.','Поведение задаётся bound','T обозначает тип, который выбирается при вызове. Ограничение Ord разрешает сравнение, а Copy — копирование значения. Это не обещание, что любой тип поддерживает эти операции. Контракт должен содержать только необходимые возможности.','fn same<T: Copy>(value: T) -> T { value }','Реализуйте minimum<T: Ord + Copy>(a, b): верните меньшее значение; при равенстве верните a.','pub fn minimum<T: Ord + Copy>(a: T, b: T) -> T {\n    a\n}','pub fn minimum<T:Ord+Copy>(a:T,b:T)->T{if a<=b{a}else{b}}',[('i32','assert_eq!(minimum(9i32,-2),-2);'),('char','assert_eq!(minimum(\'z\',\'a\'),\'a\');'),('Равенство','assert_eq!(minimum(4u32,4),4);')],['Ограничение Ord даёт сравнение <=.','Выберите a или b с помощью if.'],'Generics — не динамический «любой тип». Bound проверяется при компиляции.','Писать функцию с ограничением типа.','Почему здесь Copy','В этом упражнении bound показателен; для выбора между двумя уже принадлежащими функции значениями Copy не обязательно. Минимальный API мог бы требовать только Ord.',refs=refs,minutes=12)
add('adv-clone','generic-api','Обобщённое клонирование','Возвращаем собственный элемент из среза.','Clone и Copy различаются','Clone — явное создание копии, которое может выделять память; Copy — неявное копирование простых значений. String реализует Clone, но не Copy. Функция, читающая &[T], не может переместить его элемент из чужого среза: нужно вернуть ссылку или clone.','fn duplicate<T: Clone>(value: &T) -> T { value.clone() }','Верните первый элемент среза как Option<T>, клонируя его. Пустой срез даёт None.','pub fn first_owned<T: Clone>(values: &[T]) -> Option<T> {\n    None\n}','pub fn first_owned<T:Clone>(values:&[T])->Option<T>{values.first().cloned()}',[('String остаётся у владельца','let a=vec![String::from("Rust")]; assert_eq!(first_owned(&a),Some(String::from("Rust"))); assert_eq!(a[0],"Rust");'),('Число','assert_eq!(first_owned(&[7i32,8]),Some(7));'),('Пустой срез','assert_eq!(first_owned::<String>(&[]),None);')],['first() даёт Option<&T>.','Метод cloned() использует Clone внутри Option.'],'Не требуйте Copy, иначе String перестанет подходить.','Выбирать владение результатом и нужный bound.','Стоимость API','Если вызывающему достаточно ссылки, Option<&T> дешевле. Этот контракт специально требует собственный T — решение должно уважать его.',refs=refs)
add('adv-associated','generic-api','Ассоциированный тип','Trait с собственным типом результата.','Один контракт — разные выходы','type Item внутри trait задаёт тип, который выбирает реализация. Пользователь trait может писать Self::Item вместо фиксированного i32. Это удобно для источников данных и итераторов, когда тип результата связан с конкретной реализацией.','pub trait Source {\n    type Item;\n    fn read(&self) -> Self::Item;\n}','Реализуйте Source для IntSource: Item = i32, read возвращает value.','pub trait Source { type Item; fn read(&self) -> Self::Item; }\npub struct IntSource { pub value: i32 }\n// Добавьте impl Source for IntSource\n','pub trait Source{type Item;fn read(&self)->Self::Item;} pub struct IntSource{pub value:i32} impl Source for IntSource{type Item=i32;fn read(&self)->i32{self.value}}',[('Контракт Source','let s=IntSource{value:42}; assert_eq!(Source::read(&s),42);'),('Отрицательное значение','assert_eq!(IntSource{value:-8}.read(),-8);')],['В impl должны быть type Item = i32; и метод read.','Метод может вернуть self.value.'],'Не добавляйте отдельный похожий inherent-метод вместо реализации trait.','Реализовывать trait с associated type.','Сравните с generic trait','Associated type связывает результат с реализацией. Trait<T> может разрешать несколько реализаций для разных T; это иной дизайн контракта.',refs=refs)
add('adv-dynamic','generic-api','Полиморфизм во время выполнения','dyn Trait и неоднородные операции.','Trait object','&dyn Operation ссылается на значение с реализацией контракта; конкретный тип скрыт. Вызов метода использует динамическую диспетчеризацию. Trait должен быть dyn-compatible: например, такой метод принимает &self и возвращает фиксированный i32.','pub trait Operation { fn apply(&self, x: i32) -> i32; }','apply_all получает срез Box<dyn Operation>. Примените операции к value по порядку и верните результат. Каждый промежуточный результат помещается в i32.','pub trait Operation { fn apply(&self, x: i32) -> i32; }\npub fn apply_all(ops: &[Box<dyn Operation>], value: i32) -> i32 {\n    value\n}','pub trait Operation{fn apply(&self,x:i32)->i32;} pub fn apply_all(ops:&[Box<dyn Operation>],mut value:i32)->i32{for op in ops{value=op.apply(value);}value}',[('Порядок операций','struct Plus; impl Operation for Plus{fn apply(&self,x:i32)->i32{x+2}} struct Twice; impl Operation for Twice{fn apply(&self,x:i32)->i32{x*2}} let ops:Vec<Box<dyn Operation>>=vec![Box::new(Plus),Box::new(Twice)]; assert_eq!(apply_all(&ops,3),10);'),('Пустой конвейер','assert_eq!(apply_all(&[],7),7);')],['Заведите изменяемый результат и пройдите по ops.','Каждая операция получает результат предыдущей.'],'Не складывайте результаты независимых вызовов: условие требует конвейер.','Использовать объект trait в композиции поведения.','Когда выбрать static dispatch','Для заранее известного типа часто подходит generic функция. dyn нужен, когда набор реализаций выбирается во время выполнения или хранится неоднородно.',refs=refs,minutes=15)
refs=readings(('Brown University: ownership',BROWN+'ch04-01-what-is-ownership.html'),('The Rust Book: lifetimes',BOOK+'ch10-03-lifetime-syntax.html'),('Metanit: ссылки и время жизни',META))
add('adv-longest','lifetime-api','Жизнь возвращаемой ссылки','Аннотация связывает входы с результатом.','Lifetimes не продлевают жизнь','В longest<\'a>(a: &\'a str, b: &\'a str) -> &\'a str результат заимствован из одного из входов. Аннотация не создаёт память и не продлевает существование строки: вызывающий код обязан соблюдать связь. Здесь общий lifetime ограничивает время использования результата.','fn identity<\'a>(s: &\'a str) -> &\'a str { s }','Верните строку с большим количеством Unicode-символов. При равенстве верните a, в том числе для двух пустых строк.','pub fn longest<\'a>(a: &\'a str, b: &\'a str) -> &\'a str {\n    a\n}','pub fn longest<\'a>(a:&\'a str,b:&\'a str)->&\'a str{if a.chars().count()>=b.chars().count(){a}else{b}}',[('Выбор второй строки','assert_eq!(longest("a","rust"),"rust");'),('Unicode и равенство','assert_eq!(longest("ёж","ab"),"ёж");'),('Пустые строки','assert_eq!(longest("",""),"");')],['Не используйте len(): здесь считаются символы.','Сравните chars().count() обеих строк; >= сохраняет a при равенстве.'],'Возврат &format!(...) дал бы ссылку на временное значение.','Объяснять связь lifetimes входа и результата.','Когда аннотация не нужна','Для identity с единственной входной ссылкой действует elision: компилятор выводит связь. Для двух входных ссылок такой выбор нельзя угадать.',refs=refs,minutes=12)
add('adv-split','lifetime-api','Две ссылки на одну строку','Разделение без выделения памяти.','Заимствованные части','split_once возвращает части строки вокруг первого разделителя. Результат содержит ссылки на исходные данные, поэтому строка должна жить достаточно долго. Option явно представляет отсутствие разделителя. Срезы String всегда должны совпадать с границами UTF-8; метод строки берёт это на себя.','let pair = "name:Rust".split_once(\':\');','Верните Some((ключ, значение)) при наличии первого символа :; иначе None. Пустые ключ и значение допустимы.','pub fn split_pair(line: &str) -> Option<(&str, &str)> {\n    None\n}','pub fn split_pair(line:&str)->Option<(&str,&str)>{line.split_once(\':\')}',[('Обычная пара','assert_eq!(split_pair("name:Rust"),Some(("name","Rust")));'),('Первый разделитель','assert_eq!(split_pair("a:b:c"),Some(("a","b:c")));'),('Нет разделителя','assert_eq!(split_pair("rust"),None);'),('Пустой ключ','assert_eq!(split_pair(":ёж"),Some(("","ёж")));')],['Стандартный метод split_once уже возвращает правильные ссылки.','Передайте ему символ \':\'.'],'split() + collect() выделяет память и усложняет API без необходимости.','Создавать API с заимствованными срезами.','Почему тип обходится без явного lifetime','Все выходные ссылки происходят из единственной входной ссылки, поэтому работает lifetime elision.',refs=refs)
add('adv-cow','lifetime-api','Не копировать без причины','Cow: borrowed или owned.','Copy-on-write на уровне контракта','Cow<\'a,str> может хранить Borrowed(&\'a str) либо Owned(String). Если преобразование не требуется, можно вернуть исходный срез без аллокации. Если строку нужно изменить, создаётся собственная копия. Cow — не обещание автоматической потокобезопасности.','use std::borrow::Cow;\nlet unchanged = Cow::Borrowed("Rust");','Замените каждый символ табуляции \t одним пробелом. Если табуляций нет, верните Cow::Borrowed; иначе Cow::Owned.','use std::borrow::Cow;\npub fn normalize_tabs(text: &str) -> Cow<\'_, str> {\n    Cow::Borrowed(text)\n}','use std::borrow::Cow; pub fn normalize_tabs(text:&str)->Cow<\'_,str>{if text.contains(\'\t\'){Cow::Owned(text.replace(\'\t\'," "))}else{Cow::Borrowed(text)}}',[('Borrowed без изменения','assert!(matches!(normalize_tabs("Rust"),Cow::Borrowed(_)));'),('Owned при замене','let v=normalize_tabs("a\tb"); assert!(matches!(v,Cow::Owned(_))); assert_eq!(v,"a b");'),('Пустая строка','assert_eq!(normalize_tabs(""),"");')],['contains проверит необходимость преобразования.','Для изменяемой ветки подходит text.replace(\'\t\', " ").'],'Owned во всех случаях даст правильный текст, но нарушит условие отсутствия лишней копии.','Выбирать borrowed/owned по потребности.','Проверяем и значение, и контракт','В этом уроке тесты проверяют вариант Cow, а не только результирующую строку.',refs=refs,minutes=12)
add('adv-view','lifetime-api','Структура, которая заимствует','Lifetime в поле и impl.','Ссылка не становится владельцем','TextView<\'a> хранит &\'a str, поэтому не может пережить строку, на которую ссылается. Метод first_word возвращает срез из этой строки. split_whitespace учитывает пробельные символы, а не только обычный пробел.','pub struct TextView<\'a> { pub text: &\'a str }','Добавьте метод first_word(&self) -> &str. Возвращайте первое слово или "" для пустого/пробельного текста.','pub struct TextView<\'a> { pub text: &\'a str }\nimpl<\'a> TextView<\'a> {\n    pub fn first_word(&self) -> &str {\n        ""\n    }\n}','pub struct TextView<\'a>{pub text:&\'a str} impl<\'a> TextView<\'a>{pub fn first_word(&self)->&str{self.text.split_whitespace().next().unwrap_or("")}}',[('Первое слово','assert_eq!(TextView{text:"  hello rust"}.first_word(),"hello");'),('Табуляция','assert_eq!(TextView{text:"ёж\tдом"}.first_word(),"ёж");'),('Пустой текст','assert_eq!(TextView{text:"  "}.first_word(),"");')],['split_whitespace().next() вернёт Option<&str>.','unwrap_or("") безопасно задаёт результат при None.'],'Не возвращайте ссылку на String, созданный внутри метода.','Добавлять lifetime к структуре со ссылкой.','Владеть или заимствовать','View удобен для краткого чтения. Если объект должен храниться независимо от исходника, выберите String вместо &str.',refs=refs)
refs=readings(('Stanford CS110L: error handling',STANFORD),('The Rust Book: recoverable errors',BOOK+'ch09-02-recoverable-errors-with-result.html'),('Metanit: обработка ошибок',META))
add('adv-positive','reliable','Ошибка с понятным контрактом','Разделяем parse error и ошибку диапазона.','Result + оператор ?','? возвращает ошибку из текущей функции, если выражение дало Err, и извлекает значение из Ok. map_err переводит чужую ошибку в собственный контракт. После успешного разбора можно отдельно проверять ограничения предметной области.','let value = text.parse::<u32>().map_err(|_| "формат")?;','Верните число > 0. Ошибка parse, включая отрицательное число и переполнение u32, даёт Err("формат"). Ноль даёт Err("ноль"). Пробелы не обрезайте.','pub fn positive_count(text: &str) -> Result<u32, &\'static str> {\n    Err("формат")\n}','pub fn positive_count(text:&str)->Result<u32,&\'static str>{let n=text.parse::<u32>().map_err(|_|"формат")?;if n==0{Err("ноль")}else{Ok(n)}}',[('Корректный ввод','assert_eq!(positive_count("12"),Ok(12));'),('Ноль','assert_eq!(positive_count("0"),Err("ноль"));'),('Ошибочный формат','assert_eq!(positive_count("-1"),Err("формат")); assert_eq!(positive_count("abc"),Err("формат"));'),('Переполнение','assert_eq!(positive_count("4294967296"),Err("формат"));')],['Сначала преобразуйте parse error через map_err.','Затем проверьте n == 0.'],'unwrap превращает ожидаемую ошибку ввода в панику.','Разделять техническую и предметную ошибку.','Стабильность сообщений','Точный текст здесь часть учебного контракта. В реальном API лучше использовать типизированный error enum и отдельно отображать пользовательское сообщение.',refs=refs)
add('adv-checked','reliable','Переполнение — не сюрприз','checked_add и последовательность ошибок.','Безопасная арифметика','checked_add возвращает Option вместо переполнения. Для считывания нескольких чисел используйте split_whitespace и parse. Если следующий токен неверен, возвращайте ошибку разбора; если корректное число переполняет текущую сумму — ошибку суммы. Ошибки проверяются по порядку ввода.','let next = total.checked_add(value).ok_or("переполнение")?;','Сложите i32 из строки. Пустой ввод даёт Ok(0), неверный токен — Err("формат"), переполнение суммы — Err("переполнение").','pub fn checked_total(text: &str) -> Result<i32, &\'static str> {\n    Ok(0)\n}','pub fn checked_total(text:&str)->Result<i32,&\'static str>{let mut total=0i32;for token in text.split_whitespace(){let value=token.parse::<i32>().map_err(|_|"формат")?;total=total.checked_add(value).ok_or("переполнение")?;}Ok(total)}',[('Числа и пробелы','assert_eq!(checked_total("3 -1  4"),Ok(6));'),('Пустой ввод','assert_eq!(checked_total(""),Ok(0));'),('Неверный токен','assert_eq!(checked_total("3 x"),Err("формат"));'),('Переполнение суммы','assert_eq!(checked_total("2147483647 1"),Err("переполнение"));')],['Нужен аккумулятор с явным типом i32.','Используйте checked_add(value).ok_or("переполнение")?.'],'Обычный + может вести себя по-разному в debug/release при overflow; контракт должен быть явным.','Проверять переполнение без паники.','Отрицательные числа','checked_add учитывает обе границы i32, не только верхнюю. Дополните своё рассуждение примером -2147483648 и -1.',refs=refs,minutes=15)
add('adv-fnmut','reliable','Функция принимает поведение','Замыкание с изменяемым состоянием.','FnMut','FnMut позволяет замыканию менять захваченные переменные и вызываться несколько раз. FnOnce может потребить захват, поэтому не подходит к двум произвольным вызовам. Fn даёт более строгий контракт без изменения захвата. Вызовы FnMut требуют изменяемый доступ к самому замыканию.','let mut calls = 0;\nlet mut count = |x| { calls += 1; x + 1 };','Реализуйте twice: вызовите f для value, затем для полученного результата. Верните второй результат. T произвольный; F: FnMut(T) -> T.','pub fn twice<T, F: FnMut(T) -> T>(value: T, mut f: F) -> T {\n    value\n}','pub fn twice<T,F:FnMut(T)->T>(value:T,mut f:F)->T{let next=f(value);f(next)}',[('Преобразование','assert_eq!(twice(3,|x|x*2),12);'),('Изменяемый захват','let mut calls=0; let out=twice(0,|x|{calls+=1;x+calls}); assert_eq!(out,3); assert_eq!(calls,2);'),('Не Copy тип','assert_eq!(twice(String::from("a"),|mut s|{s.push(\'!\');s}),"a!!");')],['Сначала сохраните f(value) в отдельную переменную.','Затем вызовите f(next).'],'f(f(value)) может потребовать два одновременных mut-заимствования замыкания. Два отдельных шага проще и надёжнее.','Выбирать правильный trait замыкания.','Переиспользование','Тот же контракт работает для String и чисел. Не добавляйте Copy без причины.',refs=refs,minutes=12)
add('adv-typestate','reliable','Состояние выражается типом','Переход Draft → Published.','Type-state','Разные состояния можно представить разными структурами. Метод publish(self) потребляет Draft, так что исходный черновик больше нельзя использовать после успешного перехода. Published не имеет publish, и повторная публикация недоступна на уровне API. Это небольшая альтернатива runtime-флагам.','pub struct Draft { title: String }\npub struct Published { pub title: String }','Добавьте Draft::publish(self): пустой или пробельный title даёт Err("пустой заголовок"), иначе Ok(Published) с исходным title без обрезки.','pub struct Draft { title: String }\npub struct Published { pub title: String }\nimpl Draft {\n    pub fn new(title: String) -> Self { Self { title } }\n    pub fn publish(self) -> Result<Published, &\'static str> {\n        Err("пустой заголовок")\n    }\n}','pub struct Draft{title:String} pub struct Published{pub title:String} impl Draft{pub fn new(title:String)->Self{Self{title}} pub fn publish(self)->Result<Published,&\'static str>{if self.title.trim().is_empty(){Err("пустой заголовок")}else{Ok(Published{title:self.title})}}}',[('Переход состояния','let p=Draft::new(String::from("Rust")).publish().unwrap(); assert_eq!(p.title,"Rust");'),('Пробельный заголовок','assert!(matches!(Draft::new(String::from(" \t")).publish(),Err("пустой заголовок")));'),('Не изменять исходник','assert_eq!(Draft::new(String::from(" Rust ")).publish().unwrap().title," Rust ");')],['Проверяйте trim().is_empty(), но сохраняйте исходную строку.','Верните Ok(Published { title: self.title }).'],'&self вместо self не выражает потребление черновика. Не меняйте заданную сигнатуру.','Использовать композицию типов для перехода состояния.','Цена такого дизайна','При Err черновик тоже потреблён. Для сохранения неуспешного черновика API мог бы возвращать (Draft, Error); это важный компромисс, а не универсально лучший паттерн.',refs=refs,minutes=15)
refs=readings(('Stanford CS110L: multithreading',STANFORD),('The Rust Book: concurrency',BOOK+'ch16-00-concurrency.html'),('Metanit: многопоточность',META))
add('adv-thread','concurrency','Передаём данные потоку','move и JoinHandle.','Отдельный поток, отдельное владение','thread::spawn принимает замыкание, которое может пережить текущую функцию. move переносит Vec в замыкание. join ждёт завершения и возвращает Result: поток мог запаниковать. Здесь вход ограничен, а вычисление не должно паниковать, поэтому expect документирует внутренний инвариант, не проверяет пользовательский ввод.','let handle = std::thread::spawn(move || values.len());\nlet size = handle.join().expect("worker panicked");','Передайте Vec<u32> в новый поток, сложите элементы и верните сумму после join. Не более 1000 значений, каждое <= 1000.','pub fn sum_in_thread(values: Vec<u32>) -> u32 {\n    0\n}','pub fn sum_in_thread(values:Vec<u32>)->u32{std::thread::spawn(move||values.into_iter().sum()).join().expect("worker panicked")}',[('Сумма','assert_eq!(sum_in_thread(vec![2,3,4]),9);'),('Пустой Vec','assert_eq!(sum_in_thread(vec![]),0);'),('Одно значение','assert_eq!(sum_in_thread(vec![7]),7);')],['Используйте move ||, чтобы поток владел Vec.','Замыкание возвращает sum(), а вызывающий код — результат join().'],'Ссылка на локальный Vec не может произвольно пережить владельца.','Объяснять владение данными и ожидание потока.','Не обещаем ускорение','Для такой маленькой суммы создание потока обычно дороже вычисления. Урок изучает контракт, не оптимизацию. Unit-тесты проверяют ответ; соблюдение spawn требует чтения кода.',refs=refs,minutes=12)
add('adv-mutex','concurrency','Общее состояние без гонки','Arc + Mutex и жизненный цикл guard.','Владение и доступ — разные задачи','Arc даёт несколько владельцев выделения памяти, но сам по себе не разрешает произвольное изменение. Mutex сериализует доступ к содержимому. Guard удерживает lock до конца своей области. Не держите lock во время join потока, которому нужен этот же lock.','let shared = std::sync::Arc::new(std::sync::Mutex::new(0u32));','Создайте workers потоков; каждый увеличивает общий счётчик 100 раз под Mutex. Дождитесь всех потоков и верните итог. workers от 0 до 8.','pub fn shared_count(workers: usize) -> u32 {\n    0\n}','pub fn shared_count(workers:usize)->u32{use std::sync::{Arc,Mutex};let count=Arc::new(Mutex::new(0u32));let mut handles=Vec::new();for _ in 0..workers{let c=Arc::clone(&count);handles.push(std::thread::spawn(move||{for _ in 0..100{*c.lock().expect("poisoned")+=1;}}));}for h in handles{h.join().expect("worker panicked");}let value=*count.lock().expect("poisoned");value}',[('Несколько потоков','assert_eq!(shared_count(4),400);'),('Нет потоков','assert_eq!(shared_count(0),0);'),('Один поток','assert_eq!(shared_count(1),100);')],['Каждому потоку нужен Arc::clone, затем move-замыкание.','Сохраните JoinHandle и дождитесь всех перед чтением счётчика.'],'Arc не делает содержимое автоматически изменяемым и не заменяет Mutex.','Разделять shared ownership и синхронизацию.','Улучшение эффективности','Здесь каждый инкремент отдельный lock для демонстрации. В реальном коде локальная сумма + редкое объединение могут уменьшить contention.',refs=refs,minutes=18)
add('adv-channel','concurrency','Передаём сообщения','Канал вместо общей коллекции.','mpsc и завершение канала','mpsc::channel создаёт Sender и Receiver. Producer отправляет значения, consumer читает их. Итератор receiver заканчивается только когда все Sender уничтожены. Если оставить лишнюю копию Sender у consumer, он может ждать бесконечно. Канал здесь unbounded; для ограничения очереди используют sync_channel.','let (tx, rx) = std::sync::mpsc::channel();\n// producer: tx.send(value)\n// consumer: rx.into_iter().collect()','В отдельном потоке удвойте каждый элемент Vec<i32> и отправьте через канал. Соберите результаты в исходном порядке. Не более 1000 элементов в диапазоне -1000..=1000.','pub fn channel_double(values: Vec<i32>) -> Vec<i32> {\n    Vec::new()\n}','pub fn channel_double(values:Vec<i32>)->Vec<i32>{let(tx,rx)=std::sync::mpsc::channel();let h=std::thread::spawn(move||{for v in values{tx.send(v*2).expect("receiver closed");}});let result=rx.into_iter().collect();h.join().expect("worker panicked");result}',[('Порядок сообщений','assert_eq!(channel_double(vec![3,-2,0]),vec![6,-4,0]);'),('Пустой ввод','assert!(channel_double(vec![]).is_empty());'),('Повторы','assert_eq!(channel_double(vec![2,2]),vec![4,4]);')],['Перенесите единственный Sender в поток.','После завершения producer Sender упадёт, и rx.into_iter() завершится.'],'Не сохраняйте лишний Sender там, где ждёте завершения receiver.','Объяснять закрытие канала и порядок одного producer.','Границы модели','При нескольких producers общий порядок между ними не задан так же просто. Для unbounded канала нужно отдельно контролировать нагрузку.',refs=refs,minutes=18)
add('adv-atomic','concurrency','Атомарный счётчик','Ordering и граница обещаний.','Atomic — не универсальный lock','AtomicUsize позволяет атомарно менять число без Mutex. Relaxed обеспечивает атомарность счётчика, но не публикацию произвольных соседних данных. В этом примере join отдельно дожидается всех потоков; других данных для синхронизации нет. Для другой задачи выбор Ordering нужно обосновывать заново.','counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);','Создайте workers потоков; каждый атомарно увеличивает общий счётчик 100 раз. Дождитесь всех и верните число. workers от 0 до 8.','pub fn atomic_count(workers: usize) -> usize {\n    0\n}','pub fn atomic_count(workers:usize)->usize{use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};let count=Arc::new(AtomicUsize::new(0));let mut handles=Vec::new();for _ in 0..workers{let c=Arc::clone(&count);handles.push(std::thread::spawn(move||{for _ in 0..100{c.fetch_add(1,Ordering::Relaxed);}}));}for h in handles{h.join().expect("worker panicked");}count.load(Ordering::Relaxed)}',[('Атомарные обновления','assert_eq!(atomic_count(4),400);'),('Нет работников','assert_eq!(atomic_count(0),0);'),('Несколько запусков','for _ in 0..3{assert_eq!(atomic_count(2),200);}')],['Нужен Arc<AtomicUsize>, а не изменяемая usize.','Вызывайте fetch_add, затем join каждого handle, затем load.'],'Relaxed не делает несвязанные чтения/записи других данных упорядоченными.','Ограничивать контракт атомарного счётчика.','Не переоценивайте тесты','Несколько успешных запусков не доказывают корректность memory ordering. Нужны аргументация модели и при сложных алгоритмах специализированное тестирование.',refs=refs,minutes=18)
all_lessons=intro+old+advanced
for track in tracks:
 ids=[l['id'] for l in all_lessons if l['track']==track['id']]
 for i,id in enumerate(ids):
  l=next(x for x in all_lessons if x['id']==id);l['prerequisites']=[] if i==0 else [ids[i-1]]
 track['entry']=ids[0]
roadmap=[dict(title='Async и backend',description='Tokio, HTTP, PostgreSQL, auth и транзакции — следующий проектный блок.',outcome='Многопользовательский сервис с контрактными тестами.'),dict(title='Эксплуатация и безопасность',description='Наблюдаемость, нагрузка, бэкапы и защищённое исполнение кода.',outcome='Развёрнутый сервис с runbook и проверкой восстановления.'),dict(title='Capstone + внешнее ревью',description='Самостоятельный продукт и защита инженерных решений.',outcome='Оценка компетенций по рубрике, не автоматический титул middle.')]
# Rust character literals must escape the tab, even though tabs in strings are valid.
for lesson in all_lessons:
 for field in ('starter','solution','tests'):
  lesson[field]=lesson[field].replace("'\t'", r"'\t'")
 for section in lesson['theory']:
  if section['example']:section['example']=section['example'].replace("'\t'", r"'\t'")
(root/'backend/course.json').write_text(json.dumps(dict(version='0.2.0',tracks=tracks,modules=modules,lessons=all_lessons,roadmap=roadmap),ensure_ascii=False,indent=2))
print(f'{len(all_lessons)} lessons / {len(modules)} modules / {len(tracks)} tracks; {sum(l["kind"]=="quiz" for l in all_lessons)} quizzes; XP total {sum(l["xp"] for l in all_lessons)}')
